@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

:root {
	--background: oklch(0.98 0.01 85);
	--foreground: oklch(0.15 0.01 85);
	--card: oklch(1 0 0);
	--card-foreground: oklch(0.15 0.01 85);
	--popover: oklch(1 0 0);
	--popover-foreground: oklch(0.15 0.01 85);
	--primary: oklch(0.55 0.22 293);
	--primary-foreground: oklch(0.98 0 0);
	--secondary: oklch(0.96 0.01 85);
	--secondary-foreground: oklch(0.15 0.01 85);
	--muted: oklch(0.94 0.01 85);
	--muted-foreground: oklch(0.50 0.01 85);
	--accent: oklch(0.94 0.01 85);
	--accent-foreground: oklch(0.15 0.01 85);
	--destructive: oklch(0.55 0.22 27);
	--destructive-foreground: oklch(0.98 0 0);
	--border: oklch(0.90 0.01 85);
	--input: oklch(0.90 0.01 85);
	--ring: oklch(0.55 0.22 293);
	--chart-1: oklch(0.646 0.222 293.3);
	--chart-2: oklch(0.606 0.195 285.6);
	--chart-3: oklch(0.538 0.188 277.8);
	--chart-4: oklch(0.501 0.178 269.6);
	--chart-5: oklch(0.463 0.188 262.8);
	--radius: 0.5rem;
}

.dark {
	--background: oklch(0.12 0.01 85);
	--foreground: oklch(0.95 0.01 85);
	--card: oklch(0.18 0.01 85);
	--card-foreground: oklch(0.95 0.01 85);
	--popover: oklch(0.18 0.01 85);
	--popover-foreground: oklch(0.95 0.01 85);
	--primary: oklch(0.65 0.22 293);
	--primary-foreground: oklch(0.98 0 0);
	--secondary: oklch(0.22 0.01 85);
	--secondary-foreground: oklch(0.95 0.01 85);
	--muted: oklch(0.22 0.01 85);
	--muted-foreground: oklch(0.65 0.01 85);
	--accent: oklch(0.22 0.01 85);
	--accent-foreground: oklch(0.95 0.01 85);
	--destructive: oklch(0.55 0.22 27);
	--destructive-foreground: oklch(0.98 0 0);
	--border: oklch(0.25 0.01 85);
	--input: oklch(0.25 0.01 85);
	--ring: oklch(0.65 0.22 293);
	--chart-1: oklch(0.646 0.222 293.3);
	--chart-2: oklch(0.606 0.195 285.6);
	--chart-3: oklch(0.538 0.188 277.8);
	--chart-4: oklch(0.501 0.178 269.6);
	--chart-5: oklch(0.463 0.188 262.8);
}

@theme inline {
	--font-sans: "Inter Variable", sans-serif;
	--color-ring: var(--ring);
	--color-input: var(--input);
	--color-border: var(--border);
	--color-destructive: var(--destructive);
	--color-destructive-foreground: var(--destructive-foreground);
	--color-accent-foreground: var(--accent-foreground);
	--color-accent: var(--accent);
	--color-muted-foreground: var(--muted-foreground);
	--color-muted: var(--muted);
	--color-secondary-foreground: var(--secondary-foreground);
	--color-secondary: var(--secondary);
	--color-primary-foreground: var(--primary-foreground);
	--color-primary: var(--primary);
	--color-popover-foreground: var(--popover-foreground);
	--color-popover: var(--popover);
	--color-card-foreground: var(--card-foreground);
	--color-card: var(--card);
	--color-foreground: var(--foreground);
	--color-background: var(--background);
	--color-chart-5: var(--chart-5);
	--color-chart-4: var(--chart-4);
	--color-chart-3: var(--chart-3);
	--color-chart-2: var(--chart-2);
	--color-chart-1: var(--chart-1);
	--radius-sm: calc(var(--radius) - 4px);
	--radius-md: calc(var(--radius) - 2px);
	--radius-lg: var(--radius);
	--radius-xl: calc(var(--radius) + 4px);
	--radius-2xl: calc(var(--radius) + 8px);
	--radius-3xl: calc(var(--radius) + 12px);
	--radius-4xl: calc(var(--radius) + 16px);
}

.mesh-gradient {
	background-color: #ffffff;
	background-image:
		radial-gradient(at 0% 0%, hsla(270,100%,95%,1) 0, transparent 50%),
		radial-gradient(at 100% 0%, hsla(280,100%,95%,1) 0, transparent 50%),
		radial-gradient(at 100% 100%, hsla(260,100%,92%,1) 0, transparent 50%),
		radial-gradient(at 0% 100%, hsla(275,100%,96%,1) 0, transparent 50%);
}

@layer base {
	* {
		@apply border-border outline-ring/50;
	}
	body {
		@apply font-sans bg-background text-foreground;
	}
	html {
		@apply font-sans;
	}
}

